python3 -c "
import yaml
with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_8/projects/acr-vla-conformal-refinement/registry.yaml') as f:
    reg = yaml.safe_load(f)

exps = reg.get('experiments', {})

# Count PREPARING experiments for pi05
preparing = [(eid, e) for eid, e in exps.items() if e.get('status') == 'PREPARING' and 'pi05' in eid]
print(f'PREPARING pi05 experiments: {len(preparing)}')
for eid, e in preparing[:10]:
    print(f'  {eid}: {e.get(\"hypothesis\", \"\")[:80]}')

# Table 2 summary: what's DONE/ANALYZING/RUNNING with actual SR
print()
print('=== Table 2 Grid ===')
suites = ['spatial', 'goal', 'object', 'long']
modes = ['vla_only', 'crm', 'adaptive']

for suite in suites:
    for mode in modes:
        cells = []
        for eid, e in exps.items():
            if 'pi05' not in eid:
                continue
            status = e.get('status', '')
            if status not in ['DONE', 'ANALYZING', 'RUNNING']:
                continue
            conclusion = e.get('conclusion', '')
            if conclusion in ['killed', 'failed'] and status == 'DONE':
                continue
            hyp = (e.get('hypothesis', '') or '').lower()
            metrics = e.get('metrics', {}) or {}
            sr = metrics.get('success_rate')
            spec = e.get('spec', {}) or {}
            server = spec.get('server', e.get('server', ''))

            # Match mode
            if mode == 'vla_only' and ('vla_only' in eid or 'vla-only' in eid) and suite in hyp:
                if server and 'westd' not in server:  # exclude westd
                    for seed in ['42', '43', '44']:
                        if f's{seed}' in eid or f'seed{seed}' in eid:
                            cells.append((eid, status, conclusion, sr, server, seed))
            elif mode == 'crm' and ('crm-k2' in eid or 'crm_k2' in eid) and suite in hyp:
                for seed in ['42', '43', '44']:
                    if f's{seed}' in eid or f'seed{seed}' in eid:
                        cells.append((eid, status, conclusion, sr, server, seed))
            elif mode == 'adaptive' and 'adaptive' in eid and suite in hyp:
                for seed in ['42', '43', '44']:
                    if f's{seed}' in eid or f'seed{seed}' in eid:
                        cells.append((eid, status, conclusion, sr, server, seed))

        if cells:
            print(f'{suite}/{mode}:')
            for eid, status, conclusion, sr, server, seed in sorted(cells, key=lambda x: x[5]):
                print(f'  s{seed}: {eid} [{status}/{conclusion}] SR={sr} @{server}')
" 2>&1
